namespace MmaManager.Core.Sim.Generation.Origins;

public static partial class OriginsChapters
{
    // ===================== ERA 2: THE BACKLASH (1996-2001) =====================
    private static OriginsChapter[] Era2() => new[]
    {
        C("press-turns", 2, "A Disgrace on Cable", 30, 54, A("first-star"),
            "The sport becomes visible enough to be attacked: a promotion reaches regional size or a fighter's fame passes a threshold, and the newspapers notice.",
            World("PromotionReachesTier:Regional"),
            A(),
            A("Interest in the sport dips in the home country; carriers and sponsors grow nervous."),
            null, null,
            N("The newspapers turn",
              "{Year}. The columnists who ignored the first cards cannot ignore the tenth. A series of editorials, then a series of letters, then a series of sermons: the sport is a disgrace, a brawl with a bell, entertainment for people who should know better. A weekend magazine runs a cover story under a photograph of a ring and a single word. Fans write in to say they have never seen the fighters so polite. The campaign does not listen. Its target is not the fights but the people paid to broadcast them."),
            "The press turns: editorials and sermons call the new sport a disgrace.",
            "The Backlash is a world event; the player is never its author, so only the ByWorld variant exists."),

        C("bans-spread", 2, "The Letters to the Governors", 36, 66, A("press-turns"),
            "Politicians call for bans and regional bans begin; the longer the press campaign runs the more regions join.",
            Dated(),
            A(),
            A("Regions are marked banned: scenes there go dormant, host no shows and produce no local talent until they are sanctioned or the ban lapses. Shows in other regions are unaffected.",
              "The home country of each founding promotion is hit hardest in the first two years."),
            null, null,
            N("A map filled in, region by region",
              "{Year}. A legislator reads out a list of grievances; a second tables a bill; a third discovers that the pay-per-view cards are being watched in his own district. Within a season the letters have reached governors and mayors, and a growing list of regions, then cities, then entire states, tells promoters that they are not welcome. Halls cancel. Insurers withdraw. Some shows move across a county line and are cancelled again. Promoters who had planned for growth are suddenly planning for a way out."),
            "Politicians call for bans, and region after region closes its halls to the sport.",
            "A world event; no player variant."),

        C("carriers-drop", 2, "The Carriers Go Dark", 45, 78, A("bans-spread"),
            "The pay-per-view carriers decide the sport is more trouble than it is worth.",
            Dated(),
            A(),
            A("PPV carriers drop every promotion that is not sanctioned. PPV income stops for them until they are sanctioned or find another outlet."),
            null, null,
            N("Pay-per-view says no",
              "{Year}. It takes one telephone call from a lawyer, and then the others follow. Keystone Event Network announces it will carry no further combat cards that have not been approved by a recognised commission; the other carriers quietly agree. For the promotions whose business is the pay-per-view night, it is a death sentence: no carrier, no buys, no money. The sport has not been banned from the television. It has simply been told that the television will not take its calls."),
            "The carriers drop every unsanctioned card; pay-per-view goes dark for the sport.",
            "A world event; no player variant."),

        C("lean-years", 2, "The Lean Years", 48, 96, A("carriers-drop"),
            "Follows the carriers dropping the sport; lasts about two years in the home country.",
            Dated(),
            A(),
            A("Interest in the sport falls in the home country for two years. Only local sponsors stay. Attendance and fame growth slow; the weakest promotions fold, those that adapt survive."),
            null, null,
            N("Two years of small rooms",
              "{Year}. The cards that sold four thousand seats now sell eight hundred. Sponsors take their banners home; the mail-order men survive, the tyre shop does not. Promoters sell their own ring equipment to pay the fighters. Some leave for the one thing that still pays, a smaller venue in a friendlier place. The sport nearly dies in its own house. Those who live through it learn a habit that will last: always keep a second plan, and never again rely on a single carrier."),
            "The lean years: sponsors leave and rooms shrink, but the promotions that adapt survive.",
            "A world event; no player variant."),

        C("late-night-cable", 2, "The Channel Nobody Is Watching Says Yes", 54, 100, A("carriers-drop"),
            "The first promotion to sign a specialty or late-night cable deal.",
            First("SignMedia:SpecialtyCable"),
            A("Media:SpecialtyCable"),
            A("A small per-event rights fee and a regular late-night slot; a first screen that is not pay-per-view."),
            N("{Org} and {Partner}: the last slot of the night",
              "Pay-per-view is closed to {Org}, but at one in the morning {Partner} has an empty hour and a licence to fill it. {Founder} takes the deal in a heartbeat. The fee is tiny, the audience is insomniacs and shift workers, and nobody at the network expects it to last a month. It lasts a season, then a second. A promotion that cannot sell a night to the nation has discovered it can rent an hour to the dark."),
            N("{Partner} puts {Org} on after midnight",
              "While the carriers keep their distance, {Partner} has quietly given {Org} a late-night hour. The rights fee is small and the slot is poor, and the rest of the business is watching to see whether anyone is awake to see it. If they are, there will be more such deals; if not, {Org} will have paid for the lesson. Nobody at {Partner} expects a hit, and several of them privately hope to be wrong."),
            N("Late-night cable takes a chance",
              "{Year}. With the carriers gone, an unlikely buyer appears: a late-night channel with a hole in its schedule. {Partner} pays next to nothing and expects less. The slot falls between a re-run of a quiz show and an infomercial. Yet audience letters begin to arrive, the replays are watched in bars on three continents, and the sport has a regular screen for the first time since the carriers left. It is small, but it is a lifeline."),
            "Late-night cable takes the sport: {Partner} fills a midnight hour with fights."),

        C("rounds-and-judges", 2, "Five Minutes at a Time", 36, 84, A("press-turns"),
            "The first promotion to replace the single long round with timed rounds and rest, and to hire judges to score a fight that reaches the limit.",
            First("AdoptRules:rounds"),
            A("Rounds", "Judges"),
            A("A promotion may set rounds and time limits; fights that reach the limit can go to the judges instead of a draw."),
            N("{Org} cuts the clock into rounds",
              "{Founder} has done what the critics asked: rounds, a rest minute between them and three judges at ringside with scorecards. {Org}'s cards now end in a decision rather than a stalemate, and fighters can recover instead of simply surviving. Purists grumble that it turns a contest into a points game. Promoters elsewhere take note of something more important: the doctors approve."),
            N("{Org} adopts rounds and judges",
              "{Org} has become the first promotion in the sport to divide its fights into timed rounds, with scorecards for any bout that goes the distance. {Founder} calls it common sense; the older promoters call it a surrender. The papers, for once, find less to complain about. The rest will have to decide whether to follow, or to be the last to do so."),
            N("The long round gives way to the clock",
              "{Year}. A fight that could last twenty minutes, or thirty, or until one man simply could not continue, has always been a hard thing to sell and a harder one to defend. Now one promotion divides it into rounds of five minutes with rests between, and puts three judges at ringside to decide a fight that goes the distance. The draw, once the sport's awkward answer to a stalemate, starts to disappear. Referees and doctors are quietly relieved."),
            "Rounds and judges: the long single round gives way to the clock and the scorecard."),

        C("gloves-adopted", 2, "Padding the Knuckles", 45, 96, A("press-turns"),
            "The first promotion to require gloves of every fighter.",
            First("AdoptRules:gloves"),
            A("Gloves"),
            A("A promotion may require gloves; cuts and early stoppages change, and equipment sponsors become possible."),
            N("{Org} puts everyone in gloves",
              "Thin gloves with the fingers free: it is a small thing, and it is the thing the critics keep pointing at. {Org} makes it a rule, tells {Fighter} and every other man on the card, and waits. The fights look different, a little longer and a little cleaner, and the hands survive. {Founder} says safety was the argument and it is a good one. The cynical add that it is also a very good photograph."),
            N("{Org} makes gloves compulsory",
              "{Org} has told its fighters that bare knuckles and personal tape are over: every man on the card wears the same thin glove. Some of the veterans are unhappy. The commissioners, watching from the second row, are not. Whatever else this changes, it hands the whole sport an answer to the oldest question in the editorials. Within a week, three other promoters have asked for the name of the glove maker."),
            N("The hands get covered",
              "{Year}. For years the question from every critic has been the same: why are they not wearing gloves? The answer, historically, was that the founders disagreed. Now a promotion makes it a rule, and the others quietly check their budgets. Fighters keep their fingers free for grappling, and the cuts are fewer. Equipment makers, who have never given the sport a thought, begin to wonder how big the market for a thin glove might be."),
            "Gloves for everyone: the hands are covered and the critics lose their favourite question."),

        C("first-weight-split", 2, "Heavy and Light", 54, 108, A("rounds-and-judges", "gloves-adopted"),
            "The first promotion to crown a champion in a weight class: the line is drawn at about two hundred pounds.",
            First("CrownChampionInClass:Heavyweight"),
            A("WeightClass:Heavyweight", "WeightClass:Middleweight"),
            A("Open weight is no longer the only way to book: heavy and light divisions exist; the lighter division is called middleweight at first."),
            N("{Org} draws a line at two hundred pounds",
              "The sport's oldest unfairness has finally been admitted: a big man and a small man are not the same fight. {Org} draws a line at two hundred pounds, and in {City} {Fighter} becomes the first man to be crowned champion of a weight class. The heavies are given a division of their own; the lighter men, nearly everyone else, a name they will argue about for years. {Founder} says it is the day the sport grew up."),
            N("{Org} crowns the first weight-class champion",
              "{Org} has split its roster in two and crowned {Fighter} in {City} as the first champion of a weight class. The line is two hundred pounds. Smaller men finally get fights they can win; bigger men finally get fights worth having. Rivals will say they thought of it first. The record will say otherwise. The belt is borrowed and repainted overnight, and the trophy table is a door laid across two barrels."),
            N("The first weight limit",
              "{Year}. Eight men from eight disciplines had always meant that the largest was usually the favourite. A promoter finally decides to stop pretending otherwise: the card is split at two hundred pounds, heavy and light, and each side gets its own champion. The lighter division, which is where most fighters live, finds its feet within months. In gyms across the world, trainers begin to count pounds for the first time."),
            "The first weight split: heavy and light, with a champion for each."),

        C("scene-britain-mexico", 2, "Britain and Mexico Welcome What Others Have Banned", 48, 84, A("press-turns"),
            "A promotion takes a card to a country where it is welcome while its home regions are closed.",
            First("HoldEventInNewCountry"),
            A("CountryScene:GBR", "CountryScene:MEX"),
            A("The scenes in the United Kingdom and Mexico wake; shows banned at home can be held there."),
            N("{Org} takes the night to {City}",
              "With halls closing at home, {Org} has packed up the ring and taken its card to {City}, {Country}, where nobody has banned anything. The reception is warm and the crowd is large. {Founder} cannot decide whether to be grateful or insulted that it took exile to prove the idea works. Local fighters appear by the dozen with questions about how to join."),
            N("{Org} finds a welcome in {City}",
              "While the home regions close their halls, {Org} has found an open door in {City}, {Country}. The first card sells most of its tickets in two days. Rival promoters, struggling at home, begin to look at maps. The sport's next scene may be wherever the sport is wanted. The local papers call it a curiosity, which is better than a disgrace. After two years of locked halls at home, the mood in the promoter's party is somewhere between relief and disbelief."),
            N("Exile has its uses: London and Mexico City",
              "{Year}. Banned from the halls of its own cities, the sport takes a boat or a plane. In Britain, the boxing halls of London and Manchester rent their rings for a night and discover that a crowd will pay for something different. In Mexico City, a nation that has a hundred years of masked wrestling takes to the idea at once. Two new scenes start in the same season, born of a country's refusal to have the sport at all."),
            "Britain and Mexico open up: exiled shows find welcome crowds."),

        C("first-sanctioned-state", 2, "A Commission Says Yes", 60, 108, A("rounds-and-judges"),
            "The first promotion to win approval from an athletic commission for a card, in a region that had been closed.",
            First("SanctionedByCommission"),
            A(),
            A("A sanctioned region: PPV carriers will carry cards there again; sponsors return; the ban in that region lifts for the sanctioned promotion."),
            N("{Org} wins its licence",
              "After two years of submissions, inspections and medical questionnaires, the commission in {City} has voted to sanction {Org}'s next card. It requires rounds, judges, gloves, a physician at ringside and a list of banned moves as long as a shopping list. {Founder} has agreed to all of it. In the committee room there is a long silence and then a unanimous show of hands. The sport has been given permission to exist."),
            N("{Org} is sanctioned in {City}",
              "A regional commission has granted {Org} a licence to hold a card in {City}, the first in the sport's short history. The conditions are strict and {Founder} accepted every one. The significance is wider than one night: a sanctioned card can be carried, advertised and insured. {Org} has found the way back in, and the others are already reading the small print."),
            N("The first licence",
              "{Year}. A boxing commission that spent three years refusing to meet the promoters reverses its view after a delegation of doctors tells it the sport is safer than boxing. The rules are strict: rounds, judges, gloves, a physician. The first licensed card is held in a hall that was closed a year earlier. The carriers, who have been waiting for exactly such a piece of paper, ask whether the licence could be copied."),
            "A commission says yes: the first sanctioned card since the bans."),
    };
}
